def summarize(rows):
    """Aggregate revenue by region.

    Args:
        rows: list of dicts with 'region' (str) and 'revenue' (numeric or numeric string).

    Returns:
        dict mapping region -> total revenue as float. Rows with a missing or
        unparseable revenue are ignored.
    """
    totals = {}
    for row in rows:
        region = row.get('region')
        if region is None:
            continue
        raw = row.get('revenue')
        if raw is None:
            continue
        try:
            revenue = float(raw)
        except (TypeError, ValueError):
            continue
        totals[region] = totals.get(region, 0.0) + revenue
    return totals

from summarize import summarize


def test_basic():
    rows = [
        {'region': 'NA', 'revenue': 100},
        {'region': 'EU', 'revenue': 200},
        {'region': 'NA', 'revenue': 50},
    ]
    assert summarize(rows) == {'NA': 150.0, 'EU': 200.0}


def test_numeric_strings():
    rows = [
        {'region': 'APAC', 'revenue': '300.5'},
        {'region': 'APAC', 'revenue': '99.5'},
    ]
    assert summarize(rows) == {'APAC': 400.0}


def test_missing_revenue_ignored():
    rows = [
        {'region': 'NA', 'revenue': 10},
        {'region': 'EU'},
        {'region': 'APAC', 'revenue': None},
    ]
    assert summarize(rows) == {'NA': 10.0}


def test_unparseable_revenue_ignored():
    rows = [
        {'region': 'NA', 'revenue': 'foo'},
        {'region': 'EU', 'revenue': None},
        {'region': 'APAC', 'revenue': '42'},
    ]
    assert summarize(rows) == {'APAC': 42.0}


def test_empty_input():
    assert summarize([]) == {}


def test_returns_floats():
    rows = [{'region': 'X', 'revenue': 1}]
    result = summarize(rows)
    assert isinstance(result['X'], float)

